// The analyst-UI server against a mocked runtime and two saved-run fixtures (a cold and a warm run
// of the demo question, generated by fixtures/make_server_fixtures.py with every source value replaced
// by a synthetic one). No model, no gateway, no real H-MEM or World Model. CW_DATA_DIR points at a
// temporary directory for the whole file; config.ts resolves its paths at import time, so every
// runtime import below is dynamic and comes after the assignment. No assertion depends on today's date.

import { mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import http from "node:http";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it } from "vitest";
import type { RunResult } from "../src/loop/investigate.ts";
import type { AskFn, CwServer, ServerRuntime } from "../src/server.ts";

const DATA = mkdtempSync(join(tmpdir(), "cw-server-data-"));
process.env.CW_DATA_DIR = DATA;

const { DATA_PATHS } = await import("../src/config.ts");
const { RunStore } = await import("../src/ops/runStore.ts");
const { createServer, renderMemoMarkdown } = await import("../src/server.ts");

const fixture = (name: string) => readFileSync(new URL(`./fixtures/${name}`, import.meta.url), "utf8");
const COLD_RUN = JSON.parse(fixture("server-run-cold.json")) as Record<string, any>;
const WARM_RUN = JSON.parse(fixture("server-run-warm.json")) as Record<string, any>;
const DQ_TEXT = fixture("server-dq-latest.json");
const USL_PLAN = new URL("../../seeds/usl-plan.json", import.meta.url);
const COLD = COLD_RUN.run_id as string;
const WARM = WARM_RUN.run_id as string;
const AEP = "0000004904";
const EIX = "0000827052";
const SEMPRA = "0001032208";

function fakeRuntime(root: string) {
  const runs = new RunStore(join(root, "runs"));
  runs.save(COLD_RUN as unknown as RunResult, { source: "cli" });
  runs.save(WARM_RUN as unknown as RunResult, { source: "cli" });
  const hmem = {
    why: (id: string) => (id === "mem-1" ? { memory: { id, content: "synthetic fact" }, provenance: null, ledger: [], lines: ["synthetic fact (source synthetic)"] } : { memory: null, provenance: null, ledger: [], lines: [`No memory ${id}.`] }),
  };
  const world = {
    exportGraph: () => ({ nodes: [{ id: "utility:sec:0000000001", type: "utility", name: "Synthetic Power Co", attrs: {} }], edges: [], events: 3, byType: { utility: 1, state: 1 }, edgeTypes: { serves: 1 } }),
    utilityHistory: (cik: string) => (cik === "0000000001" ? [{ type: "serves", from: "Synthetic Power Co", to: "XX", attrs: {}, validFrom: "2024-01-01T00:00:00.000Z", validTo: null, by: "seed", open: true }] : []),
  };
  const gateway = { baseUrl: "http://127.0.0.1:8803", health: async () => ({ ok: true, templates: Array.from({ length: 57 }, (_, i) => `t${i}`) }) };
  const seeds = { utilities: [{ cik: "0000000001", name: "Synthetic Power Co", ticker: "SYN", sic: "4911", hq_state: "XX", states_served: ["XX"], station_ids: ["USW00000001"], flags: ["synthetic"] }] };
  const rt = { gateway, ollama: { model: "test-model" }, hmem, world, runs, seeds } as unknown as ServerRuntime;
  return { rt, runs };
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** A stubbed question runner: emits loop events, then saves a copy of the cold fixture under the new id. */
function fakeAsk(opts: { fail?: boolean; delayMs?: number } = {}): AskFn {
  return async (rt, req) => {
    const emit = req.onEvent!;
    await sleep(opts.delayMs ?? 5);
    emit({ type: "chunk_start", chunk: 1, carryover_tokens: 0 });
    emit({ type: "planner", chunk: 1, call: 1, valid: true, attempts: 1, tool: "search_catalogue", thought: "synthetic plan", prompt_tokens: 10, eval_tokens: 5, tokens_per_s: 100 });
    emit({ type: "tool", chunk: 1, seq: 1, tool: "search_catalogue", source: "model", fallback_reason: null, ok: true, fact: "synthetic fact", evidence_ids: [], latency_ms: 1 });
    await sleep(opts.delayMs ?? 5);
    emit({ type: "chunk_end", chunk: 1, state_tokens: 10, complete: true });
    if (opts.fail) throw new Error("synthetic failure");
    const saved = rt.runs.save({ ...COLD_RUN, run_id: req.runId!, quarter: req.quarter, mode: req.mode } as unknown as RunResult, { source: "server" });
    return { result: saved, evidence: null as never, seed: null };
  };
}

let app: CwServer | null = null;
afterEach(async () => {
  await app?.close();
  app = null;
});

async function start(o: { ask?: AskFn; dq?: boolean } = {}) {
  const root = mkdtempSync(join(tmpdir(), "cw-server-"));
  const uiDir = join(root, "ui");
  mkdirSync(uiDir);
  writeFileSync(join(uiDir, "index.html"), "<!doctype html><title>cw-test</title>");
  writeFileSync(join(uiDir, "app.js"), "export const x = 1;");
  writeFileSync(join(root, "secret.txt"), "not served");
  const dqFile = join(root, "dq-latest.json");
  if (o.dq !== false) writeFileSync(dqFile, DQ_TEXT);
  const fake = fakeRuntime(root);
  app = createServer({ runtime: fake.rt, ask: o.ask ?? fakeAsk(), uiDir, dqFile, uslPlanFile: fileURLToPath(USL_PLAN), evidenceDir: null });
  const port = await app.listen(0);
  return { ...fake, root, port, base: `http://127.0.0.1:${port}` };
}

async function call(base: string, path: string, body?: unknown, headers: Record<string, string> = {}) {
  const res = await fetch(`${base}${path}`, {
    method: body === undefined ? "GET" : "POST",
    headers: body === undefined ? headers : { "content-type": "application/json", ...headers },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let json: Record<string, any> = {};
  try {
    json = JSON.parse(text) as Record<string, any>;
  } catch {
    // not JSON (markdown, html)
  }
  return { status: res.status, body: json, text, type: res.headers.get("content-type") ?? "", headers: res.headers };
}

/** Raw request with chosen headers (fetch does not allow overriding Host). */
function raw(port: number, path: string, headers: Record<string, string>, method = "GET"): Promise<{ status: number; text: string; headers: http.IncomingHttpHeaders }> {
  return new Promise((ok, fail) => {
    const req = http.request({ host: "127.0.0.1", port, path, method, headers: { host: `127.0.0.1:${port}`, ...headers } }, (res) => {
      let buf = "";
      res.on("data", (c) => (buf += String(c)));
      res.on("end", () => ok({ status: res.statusCode ?? 0, text: buf, headers: res.headers }));
    });
    req.on("error", fail);
    req.end();
  });
}

/** Reads an SSE stream until it ends, `until` appears, or `ms` pass. */
function readSse(port: number, path: string, headers: Record<string, string>, ms: number, until?: string): Promise<{ text: string; ended: boolean; status: number }> {
  return new Promise((ok, fail) => {
    let ended = false;
    const req = http.request({ host: "127.0.0.1", port, path, headers: { host: `127.0.0.1:${port}`, ...headers } }, (res) => {
      let buf = "";
      const done = () => {
        clearTimeout(timer);
        req.destroy();
        ok({ text: buf, ended, status: res.statusCode ?? 0 });
      };
      const timer = setTimeout(done, ms);
      res.on("data", (c) => {
        buf += String(c);
        if (until && buf.includes(until)) done();
      });
      res.on("end", () => {
        ended = true;
        done();
      });
    });
    req.on("error", (e) => (String(e).includes("socket hang up") || String(e).includes("aborted") ? undefined : fail(e)));
    req.end();
  });
}

function eventsOf(text: string): { id: number | null; type: string; data: Record<string, any> }[] {
  return text
    .split("\n\n")
    .filter((b) => b.includes("event: "))
    .map((b) => {
      const id = /^id: (\d+)$/mu.exec(b)?.[1];
      return { id: id === undefined ? null : Number(id), type: /^event: (.+)$/mu.exec(b)![1]!, data: JSON.parse(/^data: (.+)$/mu.exec(b)![1]!) as Record<string, any> };
    });
}

async function waitIdle(): Promise<void> {
  for (let i = 0; i < 300; i++) {
    if (!app!.busy) return;
    await sleep(10);
  }
  throw new Error("server stayed busy");
}

describe("server: health and runs", () => {
  it("GET /api/health names the model, the gateway, the saved runs and the data files without a local path", async () => {
    const { base } = await start();
    const r = await call(base, "/api/health");
    expect(r.status).toBe(200);
    expect(r.body).toMatchObject({ ok: true, service: "crosswalk-agent", model: "test-model", gateway_ok: true, gateway_templates: 57, runs: 2, data_dir: "CW_DATA_DIR", dq_file: true, usl_plan: true, ui: true, busy_run_id: null });
    expect(r.text).not.toContain(DATA);
  });

  it("GET /api/runs lists the saved runs newest first with SGT times", async () => {
    const { base } = await start();
    const r = await call(base, "/api/runs");
    expect(r.status).toBe(200);
    expect(r.body.runs.map((x: { run_id: string }) => x.run_id)).toEqual([COLD, WARM]);
    expect(r.body.runs[0]).toMatchObject({ quarter: "CY2025Q1", mode: "cold", keys: 7, utilities: 12, chunks: 8, started_at_sgt: "2026-10-25 14:57:17 SGT", wall_s: 402.9 });
    expect(r.body.runs[1]).toMatchObject({ quarter: "CY2024Q1", mode: "warm", skipped: 5, utilities: 16 });
    expect(r.body.running).toBeNull();
  });

  it("GET /api/runs/:id serves run.json whole or slim; bad and unknown ids are 400 and 404", async () => {
    const { base, port } = await start();
    const full = await call(base, `/api/runs/${COLD}`);
    expect(full.status).toBe(200);
    expect(full.body).toMatchObject({ run_id: COLD, quarter: "CY2025Q1", mode: "cold" });
    expect(full.body.evidence).toHaveLength(77);
    const slim = await call(base, `/api/runs/${COLD}?slim=1`);
    expect(slim.body.evidence).toBeUndefined();
    expect(slim.body.planner_calls).toBeUndefined();
    expect(slim.body.join_map).toHaveLength(7);
    expect((await call(base, "/api/runs/r20260101T0000009999")).status).toBe(404);
    for (const p of ["/api/runs/not-a-run", `/api/runs/${COLD}x`, "/api/runs/..%2f..%2fsecret.txt", `/api/runs/${COLD}%2f..%2f..%2fdq`]) {
      const r = await raw(port, p, {});
      expect(r.status, p).toBe(400);
      expect(JSON.parse(r.text).code, p).toBe("bad_id");
    }
    // Dot segments are collapsed by the URL parser before routing: they reach no run lookup at all.
    for (const p of ["/api/runs/%2e%2e", `/api/runs/${COLD}/../../dq`]) expect((await raw(port, p, {})).status, p).toBe(404);
  });

  it("GET /api/runs/:id/evidence and /memo.md: every record; the note with the join map in canonical orientation and SGT citations", async () => {
    const { base } = await start();
    const ev = await call(base, `/api/runs/${COLD}/evidence`);
    expect(ev.body.records).toHaveLength(77);
    const md = await call(base, `/api/runs/${COLD}/memo.md`);
    expect(md.status).toBe(200);
    expect(md.type).toContain("text/markdown");
    expect(md.text).toContain("# Crosswalk note: CY2025Q1 vs CY2024Q1");
    expect(md.text).toContain("| cik@CY2025Q1 | cw.seed_utilities.cik | cw.frames_Revenues_CY2025Q1.cik | lpad10 | 42 / 43 | 0.977 | 42 / 43 | VERIFIED | 0001057877 (IDACORP INC) |");
    expect(md.text).toContain("| fema_state@CY2025Q1 | cw.fema_declarations_dr_2025q1.state | cw.utility_states.state | identity | 7 / 8 | 0.875 | 7 / 8 | PARTIAL | AK |");
    expect(md.text).toContain("## Citations");
    expect(md.text).toMatch(/\| ev-r20261025T14571773a0-01 \| zetaris_sql \| catalogue_list \| cw\.fema_catalogue \| https:\/\/www\.fema\.gov\/api\/open\/v1\/OpenFemaDataSets \| 2026-10-25 \d\d:\d\d:\d\d SGT \|/u);
    expect(renderMemoMarkdown(COLD_RUN, COLD_RUN.evidence)).toBe(md.text);
    const warm = await call(base, `/api/runs/${WARM}/memo.md`);
    expect(warm.text).toContain("VERIFIED (recalled; measured as cik@CY2025Q1)");
  });
});

describe("server: join map", () => {
  it("normalises every row to the counted (left) table, with both rates, verdict definitions, orphans and SQL", async () => {
    const { base } = await start();
    const r = await call(base, `/api/joinmap/${COLD}`);
    expect(r.status).toBe(200);
    expect(r.body.counts).toEqual({ keys: 7, verified: 5, partial: 1, rejected: 1, other: 0, measured_in_run: 7, recalled: 0 });
    const by = Object.fromEntries((r.body.rows as any[]).map((x) => [x.key, x]));
    // cik: recorded frames -> seed; the statement counts the seed utilities, so the row is swapped.
    expect(by["cik@CY2025Q1"]).toMatchObject({ orientation: "swapped", left: { object: "cw.seed_utilities", column: "cik" }, right: { object: "cw.frames_Revenues_CY2025Q1", column: "cik" }, transform: "lpad10", transform_applies_to: "right", matched_rows: 42, left_rows: 43, matched_keys: 42, left_keys: 43, verdict: "VERIFIED", orphans: ["0001057877 (IDACORP INC)"], recalled: false, provenance: "measured in this run", cell: "key.cik@CY2025Q1" });
    expect(by["cik@CY2025Q1"].sql).toContain("FROM (SELECT DISTINCT cik AS k FROM cw.seed_utilities) l LEFT JOIN");
    // fema_state: recorded utility_states -> FEMA in this run; the statement counts the FEMA states.
    expect(by["fema_state@CY2025Q1"]).toMatchObject({ orientation: "swapped", left: { ref: "cw.fema_declarations_dr_2025q1.state" }, right: { ref: "cw.utility_states.state" }, verdict: "PARTIAL", orphans: ["AK"], rate: 0.875 });
    expect(by["loc@CY2025Q1"]).toMatchObject({ orientation: "as_recorded", left: { object: "cw.frames_Revenues_CY2025Q1", column: "loc" }, transform_applies_to: "left" });
    expect(by["station@all"]).toMatchObject({ orientation: "as_recorded", left: { ref: "cw.seed_stations.id" }, extra: { state_equal: 56 } });
    expect(by["sic@all"]).toMatchObject({ matched_rows: 42, left_rows: 43, matched_keys: 3, left_keys: 4, verdict: "VERIFIED" });
    expect(by["cik_control@CY2025Q1"]).toMatchObject({ verdict: "REJECTED", rate: 0, transform: "identity", transform_applies_to: null });
    for (const row of r.body.rows) {
      expect(row.rate, row.key).toBeTypeOf("number");
      expect(row.rate_distinct, row.key).toBeTypeOf("number");
      expect(row.verdict_definition, row.key).toBe(r.body.definitions[row.verdict]);
    }
    expect(r.body.definitions.VERIFIED).toContain("At least 95% of the left table's rows");
    expect(r.body.definitions.PARTIAL).toContain("Between 80% and 95%");
    expect(r.body.definitions.REJECTED).toContain("Fewer than 80%");
    expect(r.body.proposals.model).toMatchObject({ proposed_by: "planner", made: 3 });
    expect(r.body.proposals.baseline).toMatchObject({ proposed_by: "baseline", made: 6 });
  });

  it("shows recalled keys as recalled, with the run they were measured as, and the live ones as measured", async () => {
    const { base } = await start();
    const r = await call(base, `/api/joinmap/${WARM}`);
    expect(r.body.counts).toMatchObject({ keys: 7, recalled: 5, measured_in_run: 2, rejected: 2 });
    const by = Object.fromEntries((r.body.rows as any[]).map((x) => [x.key, x]));
    expect(by["cik@CY2024Q1"]).toMatchObject({ recalled: true, memory_id: "mem-59", measured_as: "cik@CY2025Q1", provenance: "recalled from memory mem-59; measured as cik@CY2025Q1 in an earlier run", left: { object: "cw.seed_utilities" } });
    expect(by["fema_state@CY2024Q1"]).toMatchObject({ recalled: false, verdict: "REJECTED", matched_rows: 8, left_rows: 11, orphans: ["AK", "ME", "VT"], left: { ref: "cw.fema_declarations_dr_2024q1.state" } });
    expect(r.body.definitions.recalled).toContain("recalled from a key memory");
  });

  it("400 for a bad run id, 404 for an unknown one", async () => {
    const { base } = await start();
    expect((await call(base, "/api/joinmap/..%2fsecret")).status).toBe(400);
    expect((await call(base, "/api/joinmap/r20260101T0000009999")).status).toBe(404);
  });
});

describe("server: answer and the provenance drawer", () => {
  it("GET /api/answer/:run gives the table with a cell id per value", async () => {
    const { base } = await start();
    const r = await call(base, `/api/answer/${COLD}`);
    expect(r.status).toBe(200);
    expect(r.body).toMatchObject({ quarter: "CY2025Q1", previous: "CY2024Q1", weather_status: "measured", answered: true });
    expect(r.body.rows).toHaveLength(12);
    expect(r.body.rows[0].cells).toMatchObject({ declarations: `${AEP}.declarations`, revenue_change: `${AEP}.revenue_change`, weather_change: `${AEP}.weather_change` });
    expect(r.body.not_tested).toHaveLength(4);
  });

  it("a revenue cell names its statement, object, the one row behind it, ms, cache state and SGT time; the change recomputes from its two rows", async () => {
    const { base } = await start();
    const cur = await call(base, `/api/evidence/${COLD}/${EIX}.revenue_current`);
    expect(cur.status).toBe(200);
    const st = cur.body.statements[0];
    expect(st).toMatchObject({ template: "answer_revenue", zetaris_object: "cw.frames_Revenues_CY2025Q1", cache_state: "hit", rows_truncated: false, row_count: 12 });
    expect(st.evidence_id).toMatch(/^ev-r20261025T14571773a0-\d+$/u);
    expect(st.sql).toContain("FROM cw.frames_Revenues_CY2025Q1");
    expect(st.elapsed_ms).toBeTypeOf("number");
    expect(st.executed_at_sgt).toMatch(/^2026-10-25 \d\d:\d\d:\d\d SGT$/u);
    expect(st.rows).toHaveLength(1);
    expect(st.rows[0][0]).toBe(EIX);
    expect(cur.body.value).toBe(st.rows[0][2]);
    expect(cur.body.cell_rows_complete).toBe(true);
    const chg = await call(base, `/api/evidence/${COLD}/${EIX}.revenue_change`);
    expect(chg.body.statements).toHaveLength(2);
    const [now, before] = chg.body.statements.map((x: any) => x.rows[0][2] as number);
    expect(chg.body.value).toBeCloseTo(now! / before! - 1, 12);
    expect(chg.body.derivation).toContain("current / previous - 1");
  });

  it("a weather cell recomputes from its station rows when the run kept them, and names the missing stations when it did not", async () => {
    const { base } = await start();
    const ok = await call(base, `/api/evidence/${COLD}/${EIX}.weather_current`);
    expect(ok.body.cell_rows_complete).toBe(true);
    const s = ok.body.statements[0];
    expect(s.template).toBe("weather_quarter");
    expect(s.params.year).toBe("2025");
    const cols = s.columns as string[];
    const tdd = (s.rows as any[][]).map((r) => r[cols.indexOf("hdd")] + r[cols.indexOf("cdd")]);
    expect(ok.body.value).toBeCloseTo(tdd.reduce((a, b) => a + b, 0) / tdd.length, 9);
    const cut = await call(base, `/api/evidence/${COLD}/${AEP}.weather_previous`);
    expect(cut.body.cell_rows_complete).toBe(false);
    expect(cut.body.statements[0]).toMatchObject({ row_count: 28, rows_in_run: 20, rows_truncated: true });
    expect(cut.body.missing).toEqual(["USW00093817 (2024): row not kept in the saved run", "USW00093819 (2024): row not kept in the saved run"]);
  });

  it("a declarations cell carries the utility's state rows; a not-compared revenue keeps its value and its note", async () => {
    const { base } = await start();
    const d = await call(base, `/api/evidence/${COLD}/${AEP}.declarations`);
    const s = d.body.statements[0];
    expect(s.template).toBe("answer_fema_utilities");
    const di = (s.columns as string[]).indexOf("declarations");
    expect(s.rows.map((r: unknown[]) => r[3])).toEqual(["OK", "WV"]);
    expect(d.body.value).toBe(s.rows.reduce((a: number, r: number[]) => a + r[di]!, 0));
    const sre = await call(base, `/api/answer/${COLD}`);
    const row = sre.body.rows.find((x: any) => x.cik === SEMPRA);
    expect(row.revenue.change).toBeNull();
    expect(row.revenue.note).toContain("not compared");
    const chg = await call(base, `/api/evidence/${COLD}/${SEMPRA}.revenue_change`);
    expect(chg.body.value).toBeNull();
  });

  it("join-key and evidence-id cells; recalled keys say where they were measured", async () => {
    const { base } = await start();
    const k = await call(base, `/api/evidence/${COLD}/key.sic@all`);
    expect(k.body).toMatchObject({ kind: "join_key", value: { verdict: "VERIFIED", orphans: ["4900 (0001161728, MGE ENERGY INC)"] } });
    expect(k.body.statements).toHaveLength(2);
    expect(k.body.statements.every((x: any) => typeof x.evidence_id === "string")).toBe(true);
    const w = await call(base, `/api/evidence/${WARM}/key.cik@CY2024Q1`);
    expect(w.body.statements[0].evidence_id).toBeNull();
    expect(w.body.statements[0].note).toContain("recalled from memory mem-59, measured as cik@CY2025Q1");
    const e = await call(base, `/api/evidence/${COLD}/ev-${COLD}-01`);
    expect(e.body).toMatchObject({ kind: "evidence", statements: [{ template: "catalogue_list", zetaris_object: "cw.fema_catalogue" }] });
  });

  it("refuses cell ids outside the grammar (400) and answers 404 for cells the run lacks", async () => {
    const { base, port } = await start();
    for (const c of [`${AEP}.secret`, `${AEP}.weather_current.x`, "..%2f..%2fsecret.txt", "key.cik%40CY2025Q1%2f..", "ev-x", `${AEP.slice(1)}.declarations`, "%E0%A4%A"]) {
      const r = await raw(port, `/api/evidence/${COLD}/${c}`, {});
      expect(r.status, c).toBe(400);
    }
    expect((await call(base, `/api/evidence/${COLD}/0000000001.declarations`)).status).toBe(404);
    expect((await call(base, `/api/evidence/${COLD}/key.nothing@all`)).status).toBe(404);
    expect((await call(base, `/api/evidence/${COLD}/ev-${COLD}-999`)).status).toBe(404);
    expect((await call(base, `/api/evidence/r20260101T0000009999/${AEP}.declarations`)).status).toBe(404);
  });
});

describe("server: USL and DQ", () => {
  it("the governed model, the onboarding DQ file with its date, the last live rules and the invalid row mapped to its columns", async () => {
    const { base } = await start();
    const r = await call(base, "/api/usl");
    expect(r.status).toBe(200);
    expect(r.body).toMatchObject({ usl: "crosswalk_usl", qualified: "lightning.metastore.crosswalk.crosswalk_usl" });
    expect(r.body.tables.map((t: any) => t.name)).toEqual(["state", "sic_code", "utility", "utility_state", "fema_declaration", "station", "revenue_quarter"]);
    expect(r.body.tables[2]).toMatchObject({ name: "utility", pk: ["cik"], fks: [{ column: "sic", references: "sic_code.sic", transform: "identity" }], query_in_zetaris: "SELECT * FROM lightning.metastore.crosswalk.crosswalk_usl.utility LIMIT 10" });
    expect(r.body.fks).toHaveLength(6);
    expect(r.body.erd.edges).toContainEqual({ from: "revenue_quarter", to: "utility", label: "revenue_quarter.cik -> utility.cik (lpad10)" });
    expect(r.body.onboarding_dq).toMatchObject({ ran_at: "2026-10-25T05:46:21.146Z", ran_at_sgt: "2026-10-25 13:46:21 SGT", invalid_total: 1 });
    expect(r.body.onboarding_dq.rules).toHaveLength(6);
    expect(r.body.onboarding_dq.rules[0]).toMatchObject({ rule: "utility.sic", total: 43, valid: 42, invalid: 1, elapsed_ms: 135502 });
    // The time of the first live dq_run statement (the run itself started at 14:57:17 SGT).
    expect(r.body.live_rules).toMatchObject({ run_id: COLD, at_sgt: "2026-10-25 15:03:05 SGT", status: "matches_governed" });
    expect(r.body.live_rules.rules.map((x: any) => [x.rule, x.total, x.valid, x.invalid])).toEqual([
      ["fema_declaration.state", 116, 116, 0],
      ["utility_state.state", 97, 97, 0],
    ]);
    const sic = r.body.fks.find((f: any) => f.from === "utility.sic");
    expect(sic).toMatchObject({ onboarding: { invalid: 1 }, live: null });
    const fema = r.body.fks.find((f: any) => f.from === "fema_declaration.state");
    expect(fema).toMatchObject({ onboarding: { total: 116 }, live: { total: 116, invalid: 0 } });
    expect(r.body.invalid_rows).toEqual([{ rule: "utility.sic", table: "utility", columns: ["cik", "name", "ticker", "sic"], row: ["0001161728", "MGE ENERGY INC", "MGEE", "4900"], values: { cik: "0001161728", name: "MGE ENERGY INC", ticker: "MGEE", sic: "4900" } }]);
    expect(r.body.definitions.live).toContain("only the two rules");
  });

  it("?run= picks the run whose live rules are shown; without an onboarding file the DQ part is null", async () => {
    const { base } = await start({ dq: false });
    const r = await call(base, `/api/usl?run=${WARM}`);
    expect(r.body.live_rules.run_id).toBe(WARM);
    expect(r.body.onboarding_dq).toBeNull();
    expect(r.body.invalid_rows).toEqual([]);
    expect((await call(base, "/api/usl?run=../../x")).status).toBe(400);
  });
});

