describe("server: event streams", () => {
  it("replays a saved run as its chunk stream: every event marked replay, planner and tool steps paired per chunk, then the stream ends", async () => {
    const { port } = await start();
    const r = await readSse(port, `/api/runs/${COLD}/events`, {}, 3000);
    expect(r.status).toBe(200);
    expect(r.ended).toBe(true);
    const evs = eventsOf(r.text);
    expect(evs[0]).toMatchObject({ type: "stream", id: null, data: { mode: "replay", replay: true, run_id: COLD } });
    const body = evs.slice(1);
    expect(body.every((e) => e.data.replay === true && e.data.run_id === COLD)).toBe(true);
    expect(body[0]!.type).toBe("run_started");
    expect(body[body.length - 1]).toMatchObject({ type: "run_finished", data: { utilities: 12, keys: 7, chunks: 8 } });
    const count = (t: string) => body.filter((e) => e.type === t).length;
    expect([count("chunk_start"), count("planner"), count("tool"), count("chunk_end")]).toEqual([8, 23, 23, 8]);
    expect(body.map((e) => e.id)).toEqual(body.map((_, i) => i + 1));
    expect(body[1]).toMatchObject({ type: "chunk_start", data: { chunk: 1, recorded_at_sgt: "2026-10-25 14:57:17 SGT" } });
    expect(body[2]).toMatchObject({ type: "planner", data: { chunk: 1, call: 1, tool: "search_catalogue", valid: true } });
    expect(body[3]).toMatchObject({ type: "tool", data: { chunk: 1, seq: 1, tool: "search_catalogue", ok: true } });
    const tools = body.filter((e) => e.type === "tool").map((e) => e.data.tool);
    expect(tools).toEqual(COLD_RUN.chain.map((c: { tool: string }) => c.tool));
  });

  it("a replay resumes after Last-Event-ID; delay_ms is bounded; an unknown run is 404", async () => {
    const { base, port } = await start();
    const r = await readSse(port, `/api/runs/${WARM}/events`, { "last-event-id": "5" }, 3000);
    const ids = eventsOf(r.text).filter((e) => e.id !== null).map((e) => e.id);
    expect(ids[0]).toBe(6);
    expect((await call(base, `/api/runs/${WARM}/events?delay_ms=5000`)).status).toBe(400);
    expect((await call(base, `/api/runs/${WARM}/events?delay_ms=-1`)).status).toBe(400);
    expect((await call(base, "/api/runs/r20260101T0000009999/events")).status).toBe(404);
    const paced = await readSse(port, `/api/runs/${WARM}/events?delay_ms=1`, {}, 5000);
    expect(paced.ended).toBe(true);
    expect(eventsOf(paced.text).at(-1)!.type).toBe("run_finished");
  });

  it("a live run streams LIVE on its own URL and ends with the run; afterwards the same URL replays it", async () => {
    const { base, port } = await start({ ask: fakeAsk({ delayMs: 120 }) });
    const a = await call(base, "/api/ask", { quarter: "CY2025Q1", mode: "cold" });
    expect(a.status).toBe(202);
    expect(a.body).toMatchObject({ quarter: "CY2025Q1", mode: "cold", state: "running", events: `/api/runs/${a.body.run_id}/events` });
    const running = await call(base, `/api/runs/${a.body.run_id}`);
    expect(running.status).toBe(202);
    expect(running.body.state).toBe("running");
    expect((await call(base, "/api/runs")).body.running).toMatchObject({ run_id: a.body.run_id, quarter: "CY2025Q1" });
    const live = await readSse(port, a.body.events, {}, 3000);
    expect(live.ended).toBe(true);
    const evs = eventsOf(live.text);
    expect(evs[0]).toMatchObject({ type: "stream", data: { mode: "live", replay: false } });
    expect(evs.slice(1).map((e) => e.type)).toEqual(["run_started", "chunk_start", "planner", "tool", "chunk_end", "run_finished"]);
    expect(evs.slice(1).every((e) => e.data.replay === false && e.data.run_id === a.body.run_id)).toBe(true);
    await waitIdle();
    const after = eventsOf((await readSse(port, a.body.events, {}, 3000)).text);
    expect(after[0]!.data.mode).toBe("replay");
    expect(after.slice(1).every((e) => e.data.replay === true)).toBe(true);
  });

  it("GET /api/events carries every run's live events; Last-Event-ID and ?since replay the missed ones; a failed run publishes run_failed", async () => {
    const { base, port } = await start({ ask: fakeAsk({ fail: true }) });
    const a = await call(base, "/api/ask", { quarter: "CY2025Q1" });
    await waitIdle();
    const all = eventsOf((await readSse(port, "/api/events", { "last-event-id": "0" }, 1500, "event: run_failed")).text);
    expect(all.map((e) => e.type)).toEqual(["run_started", "chunk_start", "planner", "tool", "chunk_end", "run_failed"]);
    expect(all[5]!.data).toMatchObject({ run_id: a.body.run_id, error: "synthetic failure", replay: false });
    const fresh = await readSse(port, "/api/events", {}, 200);
    expect(fresh.text).toContain("retry: 3000");
    expect(fresh.text).not.toMatch(/^id: /mu);
    expect(eventsOf((await readSse(port, "/api/events?since=4", {}, 200)).text).map((e) => e.id)).toEqual([5, 6]);
    // The failed run was never saved: its own URL replays the ring and ends.
    const own = await readSse(port, `/api/runs/${a.body.run_id}/events`, {}, 1500);
    expect(own.ended).toBe(true);
    expect(eventsOf(own.text).at(-1)!.type).toBe("run_failed");
    expect((await call(base, "/api/ask", { quarter: "CY2025Q1" })).status).toBe(202);
    await waitIdle();
  });
});

describe("server: ask", () => {
  it("one job at a time: 409 with the busy run id; the question is validated", async () => {
    const { base } = await start({ ask: fakeAsk({ delayMs: 100 }) });
    for (const b of [{}, { quarter: "2025Q1" }, { quarter: "CY2025Q5" }, { quarter: "CY2025Q1", max_chunks: 13 }, { quarter: "CY2025Q1", max_chunks: 0 }, { quarter: "CY2025Q1", mode: "hot" }, { quarter: 2025 }]) {
      const r = await call(base, "/api/ask", b);
      expect(r.status, JSON.stringify(b)).toBe(400);
      expect(r.body.error).toBeTypeOf("string");
    }
    expect(app!.busy).toBeNull();
    const a = await call(base, "/api/ask", { quarter: "CY2025Q1", mode: "warm", max_chunks: 12, think: false });
    expect(a.status).toBe(202);
    const b = await call(base, "/api/ask", { quarter: "CY2024Q1" });
    expect(b.status).toBe(409);
    expect(b.body).toMatchObject({ code: "busy", busy_run_id: a.body.run_id });
    await waitIdle();
    expect((await call(base, "/api/runs")).body.runs).toHaveLength(3);
  });
});

