describe("server: transport safety and static files", () => {
  it("answers only to its own Host on loopback", async () => {
    const { port } = await start();
    expect((await raw(port, "/api/health", { host: "evil.example" })).status).toBe(421);
    expect((await raw(port, "/api/health", { host: `localhost:${port}` })).status).toBe(200);
    expect(() => app!.listen(0, "0.0.0.0")).toThrow(/127\.0\.0\.1 only/u);
  });

  it("CORS is closed: a foreign Origin or a cross-site fetch is refused on any method, OPTIONS is refused, no Access-Control header is sent", async () => {
    const { base, port } = await start();
    for (const path of ["/api/health", "/api/runs", `/api/joinmap/${COLD}`, "/api/events", "/"]) {
      const r = await raw(port, path, { origin: "http://evil.example" });
      expect(r.status, path).toBe(403);
      expect(JSON.parse(r.text).code).toBe("origin");
    }
    expect((await raw(port, "/api/runs", { "sec-fetch-site": "cross-site" })).status).toBe(403);
    expect((await raw(port, "/api/runs", { "sec-fetch-site": "same-origin", origin: `http://127.0.0.1:${port}` })).status).toBe(200);
    const cross = await call(base, "/api/ask", { quarter: "CY2025Q1" }, { origin: "http://evil.example" });
    expect(cross.status).toBe(403);
    const pre = await raw(port, "/api/ask", { origin: `http://127.0.0.1:${port}`, "access-control-request-method": "POST" }, "OPTIONS");
    expect(pre.status).toBe(405);
    for (const r of [pre, await raw(port, "/api/runs", {}), await raw(port, "/", {})]) {
      expect(Object.keys(r.headers).filter((h) => h.startsWith("access-control-"))).toEqual([]);
    }
    expect((await fetch(`${base}/api/ask`, { method: "POST", headers: { "content-type": "text/plain" }, body: "{}" })).status).toBe(415);
    expect((await fetch(`${base}/api/ask`, { method: "POST", headers: { "content-type": "application/json" }, body: "[1,2]" })).status).toBe(400);
    expect((await raw(port, "/api/runs", {}, "DELETE")).status).toBe(405);
    expect(app!.busy).toBeNull();
  });

  it("the inherited override, approval and conflict routes are gone", async () => {
    const { base } = await start();
    expect((await call(base, "/api/override", { conflict_id: "rc-0123456789ab", chosen: "own_filing", reason: "x" })).status).toBe(404);
    expect((await call(base, "/api/approvals/sign", { action: "override_recast", params: {} })).status).toBe(404);
    expect((await call(base, "/api/conflicts")).status).toBe(404);
    expect((await call(base, `/api/run/${COLD}`)).status).toBe(404);
  });

  it("serves the UI directory with content types and nothing outside it", async () => {
    const { base, port } = await start();
    const idx = await fetch(`${base}/`);
    expect(idx.status).toBe(200);
    expect(idx.headers.get("content-type")).toContain("text/html");
    expect(await idx.text()).toContain("<title>cw-test</title>");
    const js = await fetch(`${base}/app.js`);
    expect(js.headers.get("content-type")).toContain("text/javascript");
    expect((await fetch(`${base}/app.js`, { method: "HEAD" })).status).toBe(200);
    // Encoded parent segments, drive letters and network paths are refused outright.
    for (const p of ["/..%2fsecret.txt", "/..%5csecret.txt", "/%2e%2e%2fsecret.txt", "/C:/Windows/win.ini", "/c%3a/Windows/win.ini", "/%5c%5cserver%5cshare", "/index.html%00.txt"]) {
      const r = await raw(port, p, {});
      expect(r.status, p).toBe(403);
      expect(r.text, p).not.toContain("not served");
    }
    // Dot segments (literal or %2e-encoded) are collapsed and a leading // is read as a host by the URL parser before the file lookup: they never leave ui/.
    for (const p of ["/../secret.txt", "/ui/../secret.txt", "/../../secret.txt", "/%2e%2e/secret.txt", "//127.0.0.1/share/x"]) {
      const r = await raw(port, p, {});
      expect([403, 404], p).toContain(r.status);
      expect(r.text, p).not.toContain("not served");
    }
    expect((await raw(port, "/missing.css", {})).status).toBe(404);
    expect(JSON.parse((await raw(port, "/api/nope", {})).text).error).toContain("no route");
  });

  it("serves no files when no UI directory is configured", async () => {
    const root = mkdtempSync(join(tmpdir(), "cw-server-noui-"));
    const fake = fakeRuntime(root);
    app = createServer({ runtime: fake.rt, ask: fakeAsk(), uiDir: null, dqFile: null, uslPlanFile: null, evidenceDir: null });
    const port = await app.listen(0);
    expect((await raw(port, "/", {})).status).toBe(404);
    const h = await raw(port, "/api/health", {});
    expect(JSON.parse(h.text)).toMatchObject({ ok: true, ui: false, dq_file: false, usl_plan: false });
    expect(JSON.parse((await raw(port, "/api/usl", {})).text)).toMatchObject({ usl: null, tables: [], onboarding_dq: null });
  });
});
